from collections import Counter


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != background]
    if not points:
        return out
    rmin = min(r for r, _ in points)
    rmax = max(r for r, _ in points)
    cmin = min(c for _, c in points)
    cmax = max(c for _, c in points)
    corners = {(rmin, cmin): (-1, -1), (rmin, cmax): (-1, 1),
               (rmax, cmin): (1, -1), (rmax, cmax): (1, 1)}

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if not (0 <= nr < h and 0 <= nc < w) or grid[nr][nc] != color:
                    continue
                for y, x, sr, sc in ((r, c, -dr, -dc), (nr, nc, dr, dc)):
                    if corners.get((y, x)) != (sr, sc):
                        continue
                    y += sr
                    x += sc
                    while 0 <= y < h and 0 <= x < w:
                        if out[y][x] not in (background, color):
                            break
                        out[y][x] = color
                        y += sr
                        x += sc
    return out
